function f(n,s,o=0,c=n.length-1,M=q){for(;c>o;){if(c-o>600){const u=c-o+1,d=s-o+1,e=Math.log(u),l=.5*Math.exp(2*e/3),x=.5*Math.sqrt(e*l*(u-l)/u)*(d-u/2<0?-1:1);f(n,s,Math.max(o,Math.floor(s-d*l/u+x)),Math.min(c,Math.floor(s+(u-d)*l/u+x)),M)}const h=n[s];let i=o,t=c;for(w(n,o,s),M(n[c],h)>0&&w(n,o,c);i<t;){for(w(n,i,t),i++,t--;M(n[i],h)<0;)i++;for(;M(n[t],h)>0;)t--}M(n[o],h)===0?w(n,o,t):(t++,w(n,t,c)),t<=s&&(o=t+1),s<=t&&(c=t-1)}}function w(n,s,o){const c=n[s];n[s]=n[o],n[o]=c}function q(n,s){return n<s?-1:n>s?1:0}export{f as default};
